<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class profile extends CI_Controller {    private $limit = 10;    public function __construct() {        parent::__construct();        $this->load->helper('cookie');        $this->load->helper('xssclean');        $this->load->library('email');        $this->load->helper('email');        $this->load->helper('common');        fnIfCheckUserLoggedIn();        $this->load->model('cadmin/companymodel');    }    public function index() {        $VarUserInfo = fnGetUserLoggedInfo(1);        $ArrCompanyInfo = array();        //echo $VarUserInfo['companyid']; die;        if (isset($VarUserInfo['companyid'])) {            if ($VarUserInfo['companyid'] > 0) {                $ArrCompanyInfo = $this->companymodel->fnGetCompanyInfo($VarUserInfo['companyid']);                $ArrCompanyInfo = $ArrCompanyInfo[0];            }        }        //echo '<pre>'; print_r($ArrCompanyInfo); die();        $ArrData['ArrCompanyBasicInfo'] = $ArrCompanyInfo;        $this->load->view(CNFCOMPANY . 'profiledetails', $ArrData);    }    function updateProfile() {        $VarUserInfo = fnGetUserLoggedInfo(1);        $VarCompanyId = '';        //echo '<pre>'; print_r($VarUserInfo); die();        if (isset($VarUserInfo['companyid'])) {            if ($VarUserInfo['companyid'] > 0) {                $VarCompanyId = $VarUserInfo['companyid'];            }        }        //        $VarMsg = '';        $VarProductCapacity = xssclean($this->input->post('pc'));        $VarTurnOver = xssclean($this->input->post('to'));        $VarNumberOfEmployee = xssclean($this->input->post('ne'));        $VarZipCode = xssclean($this->input->post('zc'));        $VarContractWorker = xssclean($this->input->post('cw'));        $VarOwnershipFactory = xssclean($this->input->post('of'));        $VarMajorCustomer = xssclean($this->input->post('mc'));        $VarExportCustomer = xssclean($this->input->post('ec'));        $VarCompanyProfile = xssclean($this->input->post('cp'));        $VarCompanyName = xssclean($this->input->post('cn'));        $VarBusinessType = xssclean($this->input->post('bt'));        $VarFactorySize = xssclean($this->input->post('fz'));        $VarAddress = xssclean($this->input->post('a'));        $VarNumberOfMachine = xssclean($this->input->post('nm'));        $VarCity = xssclean($this->input->post('c'));        $VarState = xssclean($this->input->post('s'));        $VarCountry = xssclean($this->input->post('ctry'));        $VarUpdatedBy = $VarUserInfo['id'];        $ArrCompanyDetails = array('companyname' => $VarCompanyName, 'productioncapacity' => $VarProductCapacity, 'annualturnover' => $VarTurnOver, 'noofemployee' => $VarNumberOfEmployee, 'zipcode' => $VarZipCode, 'noofcontract' => $VarContractWorker, 'factoryownership' => $VarOwnershipFactory, 'majorcustomer' => $VarMajorCustomer, 'exportcustomer' => $VarExportCustomer, 'businesstype' => $VarBusinessType, 'factorysize' => $VarFactorySize, 'address' => $VarAddress, 'noofmachine' => $VarNumberOfMachine, 'city' => $VarCity, 'state' => $VarState, 'updatedby' => $VarUpdatedBy, 'dateupdated' => date('Y-m-d H:i:s'), 'country' => $VarCountry, 'companyprofile' => $VarCompanyProfile);        $VarUpdateCompanyInfo = $this->companymodel->fnUpdateCompanyBasicInfo($ArrCompanyDetails, $VarCompanyId);        if ($VarUpdateCompanyInfo) {            $ArrResult['errcode'] = 1;            $ArrResult['msg'] = 'Company Details has been updated successfully!';            $ArrResult['cid'] = $VarCompanyId;            $ArrResult['eid'] = urlencode(base64_encode($VarCompanyId));        } else {            $ArrResult['errcode'] = '-1';            $ArrResult['msg'] = '';        }        echo json_encode($ArrResult);        //    }    public function manageusers() {        $this->load->view(CNFCOMPANY . 'manageusers');    }    public function addedituser() {        $this->load->view(CNFCOMPANY . 'addedituser');    }    ////}